def is_prime(n):
    """Check whether n is a prime number."""
    if n < 2:
        return False
    if n < 4:  # 2 and 3 are prime
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True


